export const DOTS={SPACING:12,SPACING_SMALL:14,MAX_RADIUS:6,TINT:[142,148,178],MAX_ALPHA:.1,LEVELS:5,SIZE_STEP:.45,ALPHA_MOD:!0,NOISE_SCALE:.0032,FLOW_SPEED:.09,DRIFT:7,CONTRAST:2,PARALLAX:.1,UPDATE_EVERY:2,MAX_DPR:1.5},FIELD_BG="#0a0a0a",BUCKETS=Math.max(2,DOTS.LEVELS|0);export function quantise(A){let t=(A+1)*.5;return t=Math.pow(t<0?0:t>1?1:t,DOTS.CONTRAST),Math.min(BUCKETS-1,t*BUCKETS|0)}export function levelRadius(A,t=DOTS.MAX_RADIUS){const S=A/(BUCKETS-1);return t*(1-DOTS.SIZE_STEP+DOTS.SIZE_STEP*S)}export function levelFills(A=DOTS.MAX_ALPHA){const[t,S,E]=DOTS.TINT,o=[];for(let n=0;n<BUCKETS;n++){const e=A*((n+1)/BUCKETS);o.push(`rgba(${t},${S},${E},${e.toFixed(4)})`)}return o}
